import React, { useState } from "react";

const Contact = () => {
  const [form, setForm] = useState({ name: "", phone: "", message: "" });
  const [sent, setSent] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = (e) => {
    e.preventDefault();
    // This form currently just confirms receipt in the UI.
    // Wire it to a /api/contact backend route + email service if you want
    // messages delivered to your inbox automatically.
    setSent(true);
  };

  return (
    <div className="max-w-5xl mx-auto px-5 py-20 grid md:grid-cols-2 gap-14">
      <div>
        <p className="text-brass text-sm mb-3">Contact</p>
        <h1 className="text-3xl text-ivory mb-6">We'd love to hear from you</h1>
        <p className="text-stone leading-relaxed mb-8">
          Have a question about sizing, a custom order, or a bulk order for a
          wedding? Reach out and our team in Multan will get back to you.
        </p>

        <div className="flex flex-col gap-4 text-sm">
          <div>
            <p className="text-brass mb-1">Phone</p>
            <a href="tel:03116633159" className="text-ivory">0311-6633159</a>
          </div>
          <div>
            <p className="text-brass mb-1">Address</p>
            <p className="text-stone">
              5CPQ+V97, Saddar Multan Cantt Commercial Area, Multan, Pakistan
            </p>
          </div>
        </div>

        <div className="mt-8 aspect-video border border-brass/10">
          <iframe
            title="Store Location"
            className="w-full h-full grayscale"
            loading="lazy"
            src="https://www.google.com/maps?q=5CPQ%2BV97+Saddar+Multan+Cantt+Commercial+Area+Multan+Pakistan&output=embed"
          />
        </div>
      </div>

      <div>
        {sent ? (
          <div className="bg-charcoal border border-brass/10 p-8 text-center">
            <p className="text-ivory mb-2">Message received!</p>
            <p className="text-stone text-sm">
              Thank you, {form.name}. We'll get back to you at {form.phone} shortly.
            </p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div>
              <label className="text-sm text-ivory block mb-1">Name</label>
              <input
                required
                name="name"
                value={form.name}
                onChange={handleChange}
                className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
              />
            </div>
            <div>
              <label className="text-sm text-ivory block mb-1">Phone</label>
              <input
                required
                name="phone"
                value={form.phone}
                onChange={handleChange}
                className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
              />
            </div>
            <div>
              <label className="text-sm text-ivory block mb-1">Message</label>
              <textarea
                required
                name="message"
                rows={5}
                value={form.message}
                onChange={handleChange}
                className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
              />
            </div>
            <button type="submit" className="bg-brass text-ink py-3 text-sm mt-2 hover:bg-ivory transition-colors">
              Send Message
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

export default Contact;
